def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp01(x):
        return -1 if x < -1 else (1 if x > 1 else x)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def best_by_manhattan(cands, sx, sy, prefer_far=False):
        best_item = None
        best_score = None
        for item in cands:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            x, y = item[0], item[1]
            score = abs(x - sx) + abs(y - sy)
            if prefer_far:
                score = -score
            if best_score is None or score < best_score:
                best_score = score
                best_item = (x, y)
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            dx = sgn(ox - sx)
            dy = sgn(oy - sy)
            if dx == 0 and dy == 0:
                dx = 1 if gw and sx < gw - 1 else -1 if gw else 0
            return [clamp01(dx), clamp01(dy)]
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = best_by_manhattan(corners, ox, oy, prefer_far=True)
        if target is None:
            return [0, 0]
        return [clamp01(sgn(target[0] - sx)), clamp01(sgn(target[1] - sy))]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("neutral_cells")
            or []
        )
        best = best_by_manhattan(targets, sx, sy)
        if best is not None:
            return [clamp01(sgn(best[0] - sx)), clamp01(sgn(best[1] - sy))]
        # fallback: pressure opponent / defend by moving toward them
        return [clamp01(sgn(ox - sx)), clamp01(sgn(oy - sy))]

    resources = observation.get("resources") or observation.get("resource_cells") or []
    best = best_by_manhattan(resources, sx, sy)
    if best is not None:
        return [clamp01(sgn(best[0] - sx)), clamp01(sgn(best[1] - sy))]

    # fallback: move away from opponent if close, otherwise drift toward center-ish
    dx = sgn(sx - ox)
    dy = sgn(sy - oy)
    if dx == 0 and dy == 0:
        dx = 1 if gw and sx < gw // 2 else -1 if gw else 0
        dy = 1 if gh and sy < gh // 2 else -1 if gh else 0
    return [clamp01(dx), clamp01(dy)]

